1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioResult = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	// The MHPCO's price list. One row per insurable item type: what it costs to
59	// insure, and what it is insured for. Keeping both figures in a single table
60	// makes "insurable type" one fact rather than two lists that must agree.
61	const PRICE_LIST: Record<string, { basePremium: number; insuranceValue: number }> = {
62	  sword: { basePremium: 100, insuranceValue: 1000 },
63	  amulet: { basePremium: 60, insuranceValue: 600 },
64	  staff: { basePremium: 80, insuranceValue: 800 },
65	  potion: { basePremium: 40, insuranceValue: 400 },
66	  rune: { basePremium: 25, insuranceValue: 250 },
67	  moonstone: { basePremium: 25, insuranceValue: 250 },
68	};
69	
70	const DEDUCTIBLE_PER_DAMAGE = 100;
71	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
72	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
73	const FULL_REIMBURSEMENT_RATE = 1;
74	const CAP_MULTIPLIER = 2;
75	
76	const CURSE_SURCHARGE_RATE = 0.5;
77	const HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD = 5;
78	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
79	const LOYALTY_YEARS_THRESHOLD = 2;
80	const LOYALTY_DISCOUNT_RATE = 0.2;
81	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
82	
83	const BLOCK_SIZE = 3;
84	const BLOCK_BASE_PREMIUM = 60;
85	
86	// The MHPCO insures only what is on its price list. Every figure the office
87	// quotes or pays out is read through here, so an uninsurable type is rejected
88	// at the one point that knows the price list at all.
89	const priceListEntryForType = (
90	  type: string,
91	): { basePremium: number; insuranceValue: number } => {
92	  const entry = PRICE_LIST[type];
93	  if (entry === undefined) {
94	    throw new Error(`the MHPCO does not insure items of type ${type}`);
95	  }
96	
97	  return entry;
98	};
99	
100	const basePremiumForType = (type: string): number =>
101	  priceListEntryForType(type).basePremium;
102	
103	const insuranceValueForType = (type: string): number =>
104	  priceListEntryForType(type).insuranceValue;
105	
106	const countByType = (items: Item[]): Map<string, number> => {
107	  const counts = new Map<string, number>();
108	  for (const item of items) {
109	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
110	  }
111	  return counts;
112	};
113	
114	// A block is exactly BLOCK_SIZE alike items, charged as one unit.
115	const formsBlock = (count: number): boolean => count === BLOCK_SIZE;
116	
117	const groupBasePremium = (type: string, count: number): number =>
118	  formsBlock(count) ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
119	
120	const policyBasePremium = (items: Item[]): number =>
121	  [...countByType(items)].reduce(
122	    (total, [type, count]) => total + groupBasePremium(type, count),
123	    0,
124	  );
125	
126	// The MHPCO rounds in its own favour, which cuts in opposite directions for
127	// the two quantities it settles: premiums up, payouts down.
128	const roundPremiumInMHPCOsFavour = (amount: number): number => Math.ceil(amount);
129	const roundPayoutInMHPCOsFavour = (amount: number): number => Math.floor(amount);
130	
131	// Item-scoped surcharge clauses. Each applies, independently and additively,
132	// to the affected item's own base premium.
133	const ITEM_SURCHARGE_CLAUSES: {
134	  applies: (item: Item) => boolean;
135	  rate: number;
136	}[] = [
137	  {
138	    applies: (item) => item.cursed === true,
139	    rate: CURSE_SURCHARGE_RATE,
140	  },
141	  {
142	    applies: (item) =>
143	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_SURCHARGE_THRESHOLD,
144	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
145	  },
146	];
147	
148	const itemSurcharge = (item: Item): number => {
149	  const base = basePremiumForType(item.type);
150	
151	  return ITEM_SURCHARGE_CLAUSES.filter((clause) => clause.applies(item)).reduce(
152	    (total, clause) => total + base * clause.rate,
153	    0,
154	  );
155	};
156	
157	const itemSurcharges = (items: Item[]): number =>
158	  items.reduce((total, item) => total + itemSurcharge(item), 0);
159	
160	// Everything a policy-scoped clause may inspect.
161	type Policy = {
162	  items: Item[];
163	  customer: Customer;
164	  isFollowUpContract: boolean;
165	};
166	
167	// Policy-scoped modifier clauses. Each applies, independently and additively,
168	// to the policy base premium. A negative rate is a discount.
169	const POLICY_MODIFIER_CLAUSES: {
170	  applies: (policy: Policy) => boolean;
171	  rate: number;
172	}[] = [
173	  {
174	    applies: () => true,
175	    rate: FIRST_INSURANCE_SURCHARGE_RATE,
176	  },
177	  {
178	    applies: (policy) =>
179	      policy.customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
180	    rate: -LOYALTY_DISCOUNT_RATE,
181	  },
182	  {
183	    applies: (policy) => policy.isFollowUpContract,
184	    rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
185	  },
186	];
187	
188	const policyModifiers = (policy: Policy, policyBase: number): number =>
189	  POLICY_MODIFIER_CLAUSES.filter((clause) => clause.applies(policy)).reduce(
190	    (total, clause) => total + policyBase * clause.rate,
191	    0,
192	  );
193	
194	const quote = (policy: Policy): QuoteResult => {
195	  const policyBase = policyBasePremium(policy.items);
196	  const modifiedPremium =
197	    policyBase + itemSurcharges(policy.items) + policyModifiers(policy, policyBase);
198	
199	  return {
200	    premium: roundPremiumInMHPCOsFavour(modifiedPremium + PROCESSING_FEE),
201	  };
202	};
203	
204	const insuranceSum = (items: Item[]): number =>
205	  items.reduce((total, item) => total + insuranceValueForType(item.type), 0);
206	
207	// A policy issued by a quote step, tracked so later claims can draw on its cap.
208	type IssuedPolicy = {
209	  items: Item[];
210	  remainingCap: number;
211	};
212	
213	// The cap a fresh policy starts with: a multiple of the insured items' value,
214	// independent of any premium modifiers.
215	const issuePolicy = (items: Item[]): IssuedPolicy => ({
216	  items,
217	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
218	});
219	
220	// Item-scoped reimbursement clauses. Unlike the additive premium surcharges,
221	// these compete: the first applicable clause sets the rate outright, so list
222	// order is precedence. An item no clause applies to is reimbursed in full.
223	//
224	// The spec's dragon-material clause ("fully reimbursed") is deliberately not
225	// listed. Full reimbursement is already the default, and where it would
226	// collide with the high-enchantment clause the spec says the 50 % rule wins —
227	// which is what precedence gives. A dragon row would therefore be
228	// unreachable: no input distinguishes its presence from its absence.
229	const ITEM_REIMBURSEMENT_CLAUSES: {
230	  applies: (item: Item) => boolean;
231	  rate: number;
232	}[] = [
233	  {
234	    applies: (item) =>
235	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD,
236	    rate: HIGH_ENCHANTMENT_REIMBURSEMENT_RATE,
237	  },
238	];
239	
240	const reimbursementRate = (item: Item): number =>
241	  ITEM_REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.rate ??
242	  FULL_REIMBURSEMENT_RATE;
243	
244	// Reimbursement clauses read the damaged item, so a claim resolves each
245	// damage entry back to the insured item it refers to.
246	const reimbursedAmount = (item: Item, amount: number): number =>
247	  amount * reimbursementRate(item);
248	
249	// A damage entry resolved to the one insured item it is settled against.
250	type DamagedItem = {
251	  item: Item;
252	  amount: number;
253	};
254	
255	// Each damage entry is settled against a *distinct* insured item, so a claim
256	// cannot draw on the same item twice. Pairing every entry up front — rather
257	// than resolving items one at a time while totalling — keeps the "each item is
258	// claimed at most once" rule in a single place, and leaves the payout
259	// arithmetic below free of the bookkeeping.
260	const pairDamagesWithInsuredItems = (
261	  damages: Damage[],
262	  items: Item[],
263	): DamagedItem[] => {
264	  const unclaimed = [...items];
265	
266	  return damages.map((damage) => {
267	    if (damage.amount < 0) {
268	      throw new Error(
269	        `a damage amount cannot be negative, but ${damage.itemType} reports ${damage.amount}`,
270	      );
271	    }
272	
273	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
274	    if (index === -1) {
275	      throw new Error(
276	        `the policy does not cover a further ${damage.itemType} to claim against`,
277	      );
278	    }
279	
280	    return { item: unclaimed.splice(index, 1)[0], amount: damage.amount };
281	  });
282	};
283	
284	// Each damaged item carries its own deductible, and a damage smaller than the
285	// deductible contributes nothing rather than clawing money back off the claim.
286	const payoutFor = ({ item, amount }: DamagedItem): number =>
287	  Math.max(0, reimbursedAmount(item, amount) - DEDUCTIBLE_PER_DAMAGE);
288	
289	// What the incident claims, before the policy's cap is applied.
290	const claimedAmount = (incident: Incident, items: Item[]): number =>
291	  pairDamagesWithInsuredItems(incident.damages, items).reduce(
292	    (total, damaged) => total + payoutFor(damaged),
293	    0,
294	  );
295	
296	// A claim draws its payout down from the policy's remaining cap, so the
297	// policy carries less cover into any later claim against it.
298	const drawDownCap = (policy: IssuedPolicy, payout: number): IssuedPolicy => ({
299	  ...policy,
300	  remainingCap: policy.remainingCap - payout,
301	});
302	
303	// A policy never pays out more cover than it has left.
304	const cappedBy = (amount: number, remainingCap: number): number =>
305	  Math.min(amount, remainingCap);
306	
307	// Settling a claim pays out what the incident claims, capped by the cover the
308	// policy has left and rounded down. Only this final figure is rounded, so the
309	// cap draws down by the amount actually paid. Returns the payout alongside the
310	// drawn-down policy, leaving it to the caller to record.
311	const settleClaim = (
312	  incident: Incident,
313	  policy: IssuedPolicy,
314	): { result: ClaimResult; policy: IssuedPolicy } => {
315	  const claimed = claimedAmount(incident, policy.items);
316	  const covered = cappedBy(claimed, policy.remainingCap);
317	  const payout = roundPayoutInMHPCOsFavour(covered);
318	  const settled = drawDownCap(policy, payout);
319	
320	  return {
321	    result: { payout, remainingCap: settled.remainingCap },
322	    policy: settled,
323	  };
324	};
325	
326	export const runScenario = (scenario: Scenario): ScenarioResult => {
327	  let hasIssuedContract = false;
328	  const policies = new Map<number, IssuedPolicy>();
329	
330	  const results = scenario.steps.map((step, index): StepResult => {
331	    if (step.op === "claim") {
332	      const { result, policy } = settleClaim(
333	        step.incident,
334	        policies.get(step.policy)!,
335	      );
336	      policies.set(step.policy, policy);
337	
338	      return result;
339	    }
340	
341	    policies.set(index, issuePolicy(step.items));
342	
343	    const result = quote({
344	      items: step.items,
345	      customer: scenario.customer,
346	      isFollowUpContract: hasIssuedContract,
347	    });
348	    hasIssuedContract = true;
349	
350	    return result;
351	  });
352	
353	  return { results };
354	};
